mapper.select:
SELECT address, peer_pub_key AS publicKey, ong_income AS rewards, cycle AS round FROM tbl_income_info
address = #{address} AND staking_pos > 0
AND peer_pub_key = #{publicKey}
AND cycle = #{round}
ORDER BY cycle DESC

SELECT a.address, a.peer_pub_key AS publicKey, a.ong_income AS rewards, a.staking_pos AS staked, a.withdraw_pos AS unstaking, CASE WHEN a.peer = 1 THEN GREATEST(IFNULL(c.staking_pos,0) - a.staking_pos,0) ELSE a.new_pos END AS processing, IFNULL(b.next_withdrawable_pos,0) AS withdrawable, a.cycle AS round FROM tbl_income_info a LEFT JOIN tbl_income_info b ON a.address = b.address AND a.peer_pub_key = b.peer_pub_key AND a.cycle-1 = b.cycle LEFT JOIN tbl_income_info c ON a.address = c.address AND a.peer_pub_key = c.peer_pub_key AND a.cycle = c.cycle-1
a.address = #{address}
AND a.peer_pub_key = #{publicKey}
AND a.cycle = #{round}
ORDER BY a.cycle DESC, a.peer_pub_key

SELECT count(DISTINCT address) FROM tbl_governance_info WHERE peer_pub_key IN (
#{publicKey}
) AND (consensus_pos > 0 OR candidate_pos > 0)
